router.post("/", async (req, res) => {
  const key = req.header("Idempotency-Key");
  if (!key) return res.status(400).json({ error: "Idempotency-Key required" });

  const requestHash = hash({ sku: req.body.sku, quantity: req.body.quantity });

  const result = await db.transaction(async (client) => {
    const claim = await client.query(
      `INSERT INTO idempotency_keys (account_id, key, request_hash)
       VALUES ($1, $2, $3)
       ON CONFLICT (account_id, key) DO NOTHING
       RETURNING *`,
      [req.user.accountId, key, requestHash]
    );

    if (claim.rows.length === 0) {
      // key already seen — fetch what happened last time
      const existing = await client.query(
        `SELECT * FROM idempotency_keys WHERE account_id = $1 AND key = $2`,
        [req.user.accountId, key]
      );
      const prior = existing.rows[0];
      if (prior.request_hash !== requestHash) {
        return { conflict: true }; // same key, different payload
      }
      if (prior.response_body === null) {
        return { inFlight: true }; // original request still processing
      }
      return { cached: prior };
    }

    const order = await client.query(
      "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
      [req.user.accountId, req.body.sku, req.body.quantity]
    );

    await client.query(
      `UPDATE idempotency_keys SET status_code = 201, response_body = $1
       WHERE account_id = $2 AND key = $3`,
      [order.rows[0], req.user.accountId, key]
    );

    return { fresh: order.rows[0] };
  });

